import { blob, integer, primaryKey, sqliteTable, text } from 'drizzle-orm/sqlite-core';

// An organisation's synced tables (spec 02 and 03, milestone 1 subset). Every
// synced table has a single text primary key `id`, so the change log and the
// client undo log can name a row by (table, id). Ids are generated by the
// caller (client), never by SQLite.

/** A part label (spec 02 "Part label"). The id comes from the text, so two devices converge (SYNC-A12). */
export const labels = sqliteTable('labels', {
  id: text('id').primaryKey(),
  text: text('text').notNull(),
  color: text('color').notNull(),
  sort: integer('sort').notNull(),
});

export const songs = sqliteTable('songs', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  author: text('author'),
  publisher: text('publisher'),
  year: integer('year'),
  ccli: text('ccli'),
  /** Set while the song is in the trash. */
  deletedAt: integer('deleted_at'),
});

/** One part is one slide (spec 02). `sort` is 0-based and contiguous per song. */
export const songParts = sqliteTable('song_parts', {
  id: text('id').primaryKey(),
  songId: text('song_id')
    .notNull()
    .references(() => songs.id),
  sort: integer('sort').notNull(),
  labelId: text('label_id').references(() => labels.id),
  content: text('content').notNull(),
});

/**
 * A named order of a song's parts (spec 02 "Arrangement"). `partIds` is a JSON
 * array of part ids; a part may appear several times. `sort` orders a song's
 * arrangements, so "the first arrangement" (the default) is the same on every
 * device (02 Q8).
 */
export const songArrangements = sqliteTable('song_arrangements', {
  id: text('id').primaryKey(),
  songId: text('song_id')
    .notNull()
    .references(() => songs.id),
  name: text('name'),
  partIds: text('part_ids').notNull(),
  sort: integer('sort').notNull(),
});

export const presentations = sqliteTable('presentations', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  /** ISO date, `YYYY-MM-DD`. */
  eventDate: text('event_date'),
  /** Set while the presentation is in the trash (D14). */
  deletedAt: integer('deleted_at'),
  /** The presentation's own theme; null follows the organisation's default (THEME-R1). */
  themeId: text('theme_id'),
  /**
   * A template (spec 03 "Template"): a starting point for presentations, in
   * the same table with its own lists and permissions (PRES-R4, R24). It has
   * a weekly slot and a place instead of a date.
   */
  isTemplate: integer('is_template', { mode: 'boolean' }).notNull().default(false),
  /** A template's day of the week, 0 = Sunday … 6 = Saturday. */
  weekday: integer('weekday'),
  /** The time of day, `HH:MM`: a presentation's start, or a template's weekly slot. */
  time: text('time'),
  /** Where it is held (spec 03 `EventLocation`). */
  location: text('location'),
  /** When a presentation was last created from this template: the picker shows the latest first (PRES-R32). */
  lastUsedAt: integer('last_used_at'),
  /** A presentation's description (spec 03 `EventDescription`). */
  description: text('description'),
  /**
   * When it or its running order was last changed: the start page's undated
   * list and the templates page put the latest first (Dashboard.razor). The
   * server's clock once synced; null before schema 12.
   */
  updatedAt: integer('updated_at'),
});

/**
 * An item of a presentation's running order (spec 03). A song item is a
 * reference: `sourceId` names the song, and its slides are resolved from the
 * current song when shown, in the item's arrangement. A Bible item is a
 * snapshot: `sourceId` names the translation it came from, and `content`
 * holds its slides, split once when it was added (BIBLE-R12, D25). An image
 * item is a reference too: `sourceId` names the library image. A slide deck
 * is a snapshot: `content` holds its pages' picture hashes, and `sourceId`
 * is the item's own id, as there is no deck table (`SlidesItemContent`).
 */
export const presentationItems = sqliteTable('presentation_items', {
  id: text('id').primaryKey(),
  presentationId: text('presentation_id')
    .notNull()
    .references(() => presentations.id),
  type: text('type', { enum: ['song', 'bible', 'image', 'audio', 'slides'] }).notNull(),
  title: text('title').notNull(),
  sourceId: text('source_id').notNull(),
  sort: integer('sort').notNull(),
  /** The song arrangement to show; null means the song's first one (SONG-R19). */
  arrangementId: text('arrangement_id'),
  /** A Bible item's translation and slides (`BibleItemContent`), or a slide deck's pages (`SlidesItemContent`), as JSON; null for a song. */
  content: text('content'),
  /** The overlay that switches on when the item goes live and off when it leaves (TODO.md "Overlays"); null for none. */
  overlayId: text('overlay_id'),
});

/**
 * A translation the organisation has imported (spec 05 "Bible translation").
 * The id comes from the abbreviation, which is unique per organisation
 * (BIBLE-R5). Only the metadata syncs: the verses are an immutable text named
 * by `contentHash`, downloaded once by each device (docs/bibles-and-themes.md, "Bibles").
 */
export const bibles = sqliteTable('bibles', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  abbreviation: text('abbreviation').notNull(),
  language: text('language'),
  verseCount: integer('verse_count').notNull(),
  contentHash: text('content_hash').notNull(),
});

/**
 * A picture in the organisation's media library (spec 05 "Media library
 * items"). The pictures themselves are two immutable blobs named by their
 * SHA-256, `full` (fits 1920×1080) and `thumb` (fits 400×225), kept outside
 * the change log (docs/media-and-files.md, "Media"). Only the metadata syncs.
 */
export const images = sqliteTable('images', {
  id: text('id').primaryKey(),
  fileName: text('file_name').notNull(),
  /** What the blobs are: JPEG stays JPEG, everything else is WebP (MEDIA-R4). */
  contentType: text('content_type', { enum: ['image/jpeg', 'image/webp'] }).notNull(),
  fullHash: text('full_hash').notNull(),
  thumbHash: text('thumb_hash').notNull(),
  /** Of `full`, in pixels. */
  width: integer('width').notNull(),
  height: integer('height').notNull(),
  createdAt: integer('created_at').notNull(),
  /** Set while the image is in the trash (MEDIA-R8). */
  deletedAt: integer('deleted_at'),
});

/**
 * An audio file in the media library (spec 05 "Media library items"): one
 * blob named by its SHA-256, stored as it was picked (MEDIA-R5). Only the
 * metadata syncs; a device fetches the bytes of the files its presentations
 * use.
 */
export const audios = sqliteTable('audios', {
  id: text('id').primaryKey(),
  fileName: text('file_name').notNull(),
  contentType: text('content_type').notNull(),
  hash: text('hash').notNull(),
  size: integer('size').notNull(),
  createdAt: integer('created_at').notNull(),
  /** Set while the file is in the trash (MEDIA-R8). */
  deletedAt: integer('deleted_at'),
});

/**
 * An overlay (spec 03 "OverlaySlide"): text, a picture, or both, shown above
 * the live slide (LIVE-R15). The picture is one of the media library's, by
 * id: a trashed picture still shows, a purged one is left out. `sort` is the
 * order of creation (spec 03 has no reordering).
 */
export const overlays = sqliteTable('overlays', {
  id: text('id').primaryKey(),
  title: text('title').notNull(),
  content: text('content'),
  imageId: text('image_id'),
  sort: integer('sort').notNull(),
});

/**
 * An output a presentation can send to (spec 04 `RemoteDisplay`): a public
 * output, which anyone opens at `/watch/{code}` (LIVE-R30), or a saved screen,
 * a TV that opens `/display?id={code}` (spec 04 §5). The code is registered
 * with the server's global tables, so an anonymous page finds the
 * organisation by it.
 */
export const displays = sqliteTable('displays', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  code: text('code').notNull(),
  kind: text('kind', { enum: ['public', 'screen'] }).notNull(),
  /** When it was made: Skärmar and the live panel list outputs in that order (RemoteDisplayService.cs). Null before schema 12. */
  createdAt: integer('created_at'),
});

/** The organisation's settings, one row each: `defaultThemeId` so far (THEME-R4). */
export const orgSettings = sqliteTable('org_settings', {
  id: text('id').primaryKey(),
  value: text('value').notNull(),
});

/**
 * Not synced. A translation's text, one row per book, named by the hash of
 * the whole text (`bibleTextHash`). The server keeps what devices upload; a
 * device keeps what it downloaded or imported, through resets.
 */
export const bibleTexts = sqliteTable(
  'bible_texts',
  {
    hash: text('hash').notNull(),
    book: text('book').notNull(),
    sort: integer('sort').notNull(),
    /** The book's verses as JSON: `[[chapter, verse, text], …]`. */
    chunk: text('chunk').notNull(),
  },
  (t) => [primaryKey({ columns: [t.hash, t.book] })],
);

/** Not synced. One row per complete text in `bible_texts`, written last, so a text is there only when all of it is. */
export const bibleBlobs = sqliteTable('bible_blobs', {
  hash: text('hash').primaryKey(),
  verseCount: integer('verse_count').notNull(),
});

/**
 * Not synced. Which media blobs this database knows, by hash. On a device the
 * row holds the bytes, so pictures show offline and through resets; on the
 * server it records that the blob is in the media storage (`bytes` is null),
 * which is what `addImage` checks. `receivedAt` is this database's own clock:
 * a blob nothing names is removed only after a grace period, so one uploaded
 * just before its `addImage` is pushed is never taken away.
 */
export const mediaBlobs = sqliteTable('media_blobs', {
  hash: text('hash').primaryKey(),
  contentType: text('content_type').notNull(),
  size: integer('size').notNull(),
  bytes: blob('bytes', { mode: 'buffer' }),
  receivedAt: integer('received_at').notNull(),
});

/**
 * Not synced. The presentations this device keeps every file of, whatever
 * their date ("Tillgänglig offline", docs/media-and-files.md "Which files a device keeps"):
 * a choice for this device, not for the organisation.
 */
export const pinnedPresentations = sqliteTable('pinned_presentations', {
  id: text('id').primaryKey(),
  pinnedAt: integer('pinned_at').notNull(),
});

/**
 * Not synced. The translations this device keeps the text of ("Tillgänglig
 * offline", docs/bibles-and-themes.md "Bibles"): a choice for this device, not for the
 * organisation. By id, so a re-imported translation stays kept. A desktop
 * host keeps every text whatever this says.
 */
export const keptBibles = sqliteTable('kept_bibles', {
  id: text('id').primaryKey(),
  keptAt: integer('kept_at').notNull(),
});

export const schema = {
  labels,
  songs,
  songParts,
  songArrangements,
  presentations,
  presentationItems,
  bibles,
  orgSettings,
  images,
  displays,
  audios,
  overlays,
  bibleTexts,
  bibleBlobs,
  mediaBlobs,
  pinnedPresentations,
  keptBibles,
};

/** Synced tables in parent-before-child order. */
export const syncedTables = [labels, songs, songParts, songArrangements, presentations, presentationItems, bibles, orgSettings, images, displays, audios, overlays];

export type Label = typeof labels.$inferSelect;
export type Song = typeof songs.$inferSelect;
export type SongPart = typeof songParts.$inferSelect;
export type SongArrangement = typeof songArrangements.$inferSelect;
export type Presentation = typeof presentations.$inferSelect;
export type PresentationItem = typeof presentationItems.$inferSelect;
export type Bible = typeof bibles.$inferSelect;
export type LibraryImage = typeof images.$inferSelect;
export type Display = typeof displays.$inferSelect;
export type LibraryAudio = typeof audios.$inferSelect;
export type Overlay = typeof overlays.$inferSelect;

/** Bumped whenever a synced table changes shape; part of the pull cookie's scope. */
export const SCHEMA_VERSION = 12;

/**
 * The first version `orgDdl` makes. The migrations from milestone 1 on were
 * dropped before the first release (2026-10-29): a database made before then
 * is not brought up to date. The numbering goes on from there rather than
 * starting again at 1, so such a database is never taken for a current one.
 */
export const SCHEMA_BASELINE = 11;

// Hand-written DDL of the current version: the columns must match the Drizzle
// tables above, which a test checks. A database made by an older version is
// brought up to date by `orgMigrations` instead (see `orgSchemaPlan`).
export const orgDdl: string[] = [
  `CREATE TABLE IF NOT EXISTS labels (id TEXT PRIMARY KEY NOT NULL, text TEXT NOT NULL, color TEXT NOT NULL,
     sort INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS songs (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, author TEXT,
     publisher TEXT, year INTEGER, ccli TEXT, deleted_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS song_parts (id TEXT PRIMARY KEY NOT NULL,
     song_id TEXT NOT NULL REFERENCES songs(id), sort INTEGER NOT NULL,
     label_id TEXT REFERENCES labels(id), content TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS song_arrangements (id TEXT PRIMARY KEY NOT NULL,
     song_id TEXT NOT NULL REFERENCES songs(id), name TEXT, part_ids TEXT NOT NULL, sort INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS presentations (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, event_date TEXT,
     deleted_at INTEGER, theme_id TEXT, is_template INTEGER NOT NULL DEFAULT 0, weekday INTEGER, time TEXT,
     location TEXT, last_used_at INTEGER, description TEXT, updated_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS presentation_items (id TEXT PRIMARY KEY NOT NULL,
     presentation_id TEXT NOT NULL REFERENCES presentations(id), type TEXT NOT NULL, title TEXT NOT NULL,
     source_id TEXT NOT NULL, sort INTEGER NOT NULL, arrangement_id TEXT, content TEXT, overlay_id TEXT)`,
  `CREATE TABLE IF NOT EXISTS bibles (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, abbreviation TEXT NOT NULL,
     language TEXT, verse_count INTEGER NOT NULL, content_hash TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS org_settings (id TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS images (id TEXT PRIMARY KEY NOT NULL, file_name TEXT NOT NULL, content_type TEXT NOT NULL,
     full_hash TEXT NOT NULL, thumb_hash TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL,
     created_at INTEGER NOT NULL, deleted_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS displays (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, code TEXT NOT NULL, kind TEXT NOT NULL, created_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS audios (id TEXT PRIMARY KEY NOT NULL, file_name TEXT NOT NULL, content_type TEXT NOT NULL,
     hash TEXT NOT NULL, size INTEGER NOT NULL, created_at INTEGER NOT NULL, deleted_at INTEGER)`,
  `CREATE TABLE IF NOT EXISTS overlays (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, content TEXT, image_id TEXT,
     sort INTEGER NOT NULL)`,
  // Not synced: what this database keeps for itself (see the tables above).
  `CREATE TABLE IF NOT EXISTS bible_texts (hash TEXT NOT NULL, book TEXT NOT NULL, sort INTEGER NOT NULL, chunk TEXT NOT NULL,
     PRIMARY KEY (hash, book))`,
  `CREATE TABLE IF NOT EXISTS bible_blobs (hash TEXT PRIMARY KEY NOT NULL, verse_count INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS media_blobs (hash TEXT PRIMARY KEY NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL,
     bytes BLOB, received_at INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS pinned_presentations (id TEXT PRIMARY KEY NOT NULL, pinned_at INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS kept_bibles (id TEXT PRIMARY KEY NOT NULL, kept_at INTEGER NOT NULL)`,
];

/** The statements that take a database from version `n - 1` to `n`, for every `n` above SCHEMA_BASELINE. */
export const orgMigrations: Record<number, string[]> = {
  // A presentation's description (spec 03) and when it was last changed; when an output was made.
  12: ['ALTER TABLE presentations ADD COLUMN description TEXT', 'ALTER TABLE presentations ADD COLUMN updated_at INTEGER', 'ALTER TABLE displays ADD COLUMN created_at INTEGER'],
};

/** Where a database records its schema version. One made before versions were recorded has no row. */
export const schemaMetaDdl = `CREATE TABLE IF NOT EXISTS _schema (one INTEGER PRIMARY KEY CHECK (one = 1), version INTEGER NOT NULL)`;

/**
 * What to run, in one transaction, to bring an organisation database to
 * SCHEMA_VERSION. `version` is the row in `_schema` (null when there is none)
 * and `hasTables` whether the synced tables exist yet.
 */
export function orgSchemaPlan(version: number | null, hasTables: boolean): string[] {
  if (version === null && !hasTables) return [...orgDdl, `INSERT OR REPLACE INTO _schema (one, version) VALUES (1, ${SCHEMA_VERSION})`];
  if (version === null || version < SCHEMA_BASELINE)
    throw new Error(`the database has schema ${version ?? 'from before versions were recorded'}, made before this app's first, ${SCHEMA_BASELINE}: delete it and start again`);
  if (version > SCHEMA_VERSION) throw new Error(`the database has schema ${version}, newer than this app's ${SCHEMA_VERSION}`);
  if (version === SCHEMA_VERSION) return [];
  const steps: string[] = [];
  for (let v = version + 1; v <= SCHEMA_VERSION; v++) steps.push(...orgMigrations[v]!);
  steps.push(`INSERT OR REPLACE INTO _schema (one, version) VALUES (1, ${SCHEMA_VERSION})`);
  return steps;
}

/** The two reads `orgSchemaPlan` needs, as SQL: run after `schemaMetaDdl`. */
export const schemaStateSql = {
  version: 'SELECT version FROM _schema WHERE one = 1',
  hasTables: "SELECT count(*) AS n FROM sqlite_master WHERE type = 'table' AND name = 'songs'",
};

type Rows = Record<string, unknown>[];

function planFor(versionRows: Rows, tableRows: Rows): string[] {
  const version = versionRows[0] ? Number(versionRows[0].version) : null;
  return orgSchemaPlan(version, Number(tableRows[0]?.n ?? 0) > 0);
}

/**
 * Brings an organisation database to SCHEMA_VERSION, for the synchronous
 * server drivers. `run` executes one statement and returns its rows;
 * `atomically` runs its callback as one transaction.
 */
export function migrateOrgSchemaSync(run: (sql: string) => Rows, atomically: (fn: () => void) => void): void {
  run(schemaMetaDdl);
  const plan = planFor(run(schemaStateSql.version), run(schemaStateSql.hasTables));
  if (plan.length) atomically(() => plan.forEach((s) => run(s)));
}

/** The same for an asynchronous connection (the clients). */
export async function migrateOrgSchema(run: (sql: string) => Promise<Rows>, atomically: (fn: () => Promise<void>) => Promise<void>): Promise<void> {
  await run(schemaMetaDdl);
  const plan = planFor(await run(schemaStateSql.version), await run(schemaStateSql.hasTables));
  if (plan.length) {
    await atomically(async () => {
      for (const s of plan) await run(s);
    });
  }
}
